    function _dismissSettings() {
        const overlay = document.getElementById('settingsOverlay');
        const modal = overlay.querySelector('.settings-modal');
        modal.classList.remove('is-opening');
        modal.classList.add('is-closing');
        overlay.classList.remove('show');
        modal.addEventListener('animationend', () => {
            modal.classList.remove('is-closing');
            modal.style.opacity = '0';
            overlay.style.display = 'none';
        }, { once: true });
    }

    function openSettings() {
        tempTheme = localStorage.getItem('gnTheme') || 'auto';
        tempAccent = localStorage.getItem('gnAccent') || '#007AFF';
        tempColorScheme = localStorage.getItem('gnColor') || 'blue';
        document.documentElement.setAttribute('data-color', tempColorScheme);
        updateSettingsUI();
        updateColorSchemeUI();
        updateNoneBtn(tempAccent === 'none');
        if (tempAccent !== 'none') syncWheelToHex(tempAccent);

        const overlay = document.getElementById('settingsOverlay');
        const modal = overlay.querySelector('.settings-modal');
        const btn = document.querySelector('.icon-btn[title="Settings"]');

        // Compute offset from modal center (viewport center) to button center
        if (btn) {
            const br = btn.getBoundingClientRect();
            const btnCx = br.left + br.width / 2;
            const btnCy = br.top  + br.height / 2;
            const vw = window.innerWidth;
            const vh = window.innerHeight;
            const dx = btnCx - vw / 2;
            const dy = btnCy - vh / 2;
            // scale factor: button size / modal size (approx)
            const modalW = Math.min(460, vw - 32);
            const sc = br.width / modalW;
            modal.style.setProperty('--s-dx', dx + 'px');
            modal.style.setProperty('--s-dy', dy + 'px');
            modal.style.setProperty('--s-scale', sc);
        }

        modal.classList.remove('is-closing');
        overlay.style.display = 'flex';
        // kick off background fade
        requestAnimationFrame(() => {
            overlay.classList.add('show');
            modal.classList.add('is-opening');
        });
        modal.addEventListener('animationend', () => {
            modal.classList.remove('is-opening');
            modal.style.opacity = '1';
            modal.style.transform = '';
        }, { once: true });

        initColorWheel();
    }

